EMPRENDECLARO_PAYLOAD
[[ "$(sha256sum "$installer_tmp" | cut -d ' ' -f 1)" == '2b99f6b9ae8de3fec80f7d4e81c00c60d321e880a7f78c41da9ac060e8056223' ]] || exit 74
tar -xzf "$installer_tmp" --no-same-owner index.html assets/hero-mountains.webp assets/hero-woman.webp revision.html
chmod 644 index.html revision.html assets/hero-mountains.webp assets/hero-woman.webp
chmod 755 assets
# Notify Opalstack only after the verified index has been installed.
/usr/bin/python3.6 - "$app_uuid" <<'OPALSTACK_COMPLETE'
import http.client, json, os, re, sys
app_uuid = sys.argv[1]
if not re.fullmatch(r'[0-9a-f-]{36}', app_uuid):
    sys.exit('Invalid application identifier')
api_host = os.environ.get('API_URL', '').replace('https://', '').rstrip('/')
if api_host != 'my.opalstack.com':
    sys.exit('Unexpected Opalstack API host')
token = os.environ.get('OPAL_TOKEN')
if not token:
    sys.exit('Missing installer authorization')
connection = http.client.HTTPSConnection(api_host, timeout=30)
connection.request('POST', '/api/v1/app/installed/', json.dumps([{'id': app_uuid}]), headers={'Content-Type': 'application/json', 'Authorization': 'Token ' + token})
response = connection.getresponse()
response.read()
if not 200 <= response.status < 300:
    sys.exit('Completion notification failed: HTTP ' + str(response.status))
print('Opalstack completion confirmed.')
OPALSTACK_COMPLETE
